{"question": "Generate a SQL query to retrieve the total sales amount grouped by product category for the year 2023 from the 'sales' table. The table has columns: sale_id, product_id, category, amount, sale_date.", "answer": "SELECT category, SUM(amount) AS total_sales FROM sales WHERE YEAR(sale_date) = 2023 GROUP BY category;", "subject": "SQL", "category": "Data Retrieval"}
{"question": "Write a SQL query to find the top 3 customers with the highest total order value from the 'orders' table. Columns: customer_id, order_id, total_value.", "answer": "SELECT customer_id, SUM(total_value) AS total_order_value FROM orders GROUP BY customer_id ORDER BY total_order_value DESC LIMIT 3;", "subject": "SQL", "category": "Aggregation"}
{"question": "Create a SQL query to identify employees who have not been assigned to any project in the 'projects' table. Tables: 'employees' (emp_id, name), 'projects' (project_id, emp_id).", "answer": "SELECT e.name FROM employees e LEFT JOIN projects p ON e.emp_id = p.emp_id WHERE p.project_id IS NULL;", "subject": "SQL", "category": "Set Operations"}
{"question": "Generate a SQL query to calculate the month-over-month growth rate of revenue for each month in 2023 from the 'revenue' table. Columns: month, revenue.", "answer": "SELECT month, revenue, (revenue - LAG(revenue) OVER (ORDER BY month)) * 100.0 / LAG(revenue) OVER (ORDER BY month) AS growth_rate FROM revenue WHERE month >= '2023-02';", "subject": "SQL", "category": "Window Functions"}
{"question": "Write a SQL query to pivot the 'sales' table to show total sales for each product as columns (ProductA, ProductB, ProductC) for each region. Table: 'sales' (region, product, amount).", "answer": "SELECT region, SUM(CASE WHEN product = 'ProductA' THEN amount ELSE 0 END) AS ProductA, SUM(CASE WHEN product = 'ProductB' THEN amount ELSE 0 END) AS ProductB, SUM(CASE WHEN product = 'ProductC' THEN amount ELSE 0 END) AS ProductC FROM sales GROUP BY region;", "subject": "SQL", "category": "Pivot Data"}
{"question": "Create a SQL query to find duplicate emails in the 'users' table. Table: 'users' (id, email).", "answer": "SELECT email FROM users GROUP BY email HAVING COUNT(*) > 1;", "subject": "SQL", "category": "Data Quality"}
{"question": "Write a SQL query to retrieve the second highest salary from the 'employees' table. Table: 'employees' (id, name, salary).", "answer": "SELECT MAX(salary) AS second_highest_salary FROM employees WHERE salary < (SELECT MAX(salary) FROM employees);", "subject": "SQL", "category": "Ranking"}
{"question": "Generate a SQL query to list all orders placed by customers who have made more than 5 orders. Tables: 'orders' (order_id, customer_id), 'customers' (customer_id, name).", "answer": "SELECT o.order_id, c.name FROM orders o JOIN customers c ON o.customer_id = c.customer_id WHERE o.customer_id IN (SELECT customer_id FROM orders GROUP BY customer_id HAVING COUNT(*) > 5);", "subject": "SQL", "category": "Subqueries"}
{"question": "Write a SQL query to calculate the running total of sales for each day from the 'daily_sales' table. Columns: sale_date, amount.", "answer": "SELECT sale_date, amount, SUM(amount) OVER (ORDER BY sale_date) AS running_total FROM daily_sales;", "subject": "SQL", "category": "Window Functions"}
{"question": "Create a SQL query to find the longest streak of consecutive days where sales were above 1000. Table: 'sales' (sale_date, amount).", "answer": "WITH flagged AS (SELECT sale_date, amount, sale_date - INTERVAL ROW_NUMBER() OVER (ORDER BY sale_date) DAY AS grp FROM sales WHERE amount > 1000), streaks AS (SELECT grp, COUNT(*) AS streak_length FROM flagged GROUP BY grp) SELECT MAX(streak_length) FROM streaks;", "subject": "SQL", "category": "Advanced Analytics"}
{"question": "Generate a SQL query to find the total revenue per product category for orders placed in the last 30 days. The database has tables 'orders' (order_id, customer_id, order_date, total_amount) and 'order_items' (order_id, product_id, quantity, price). Assume 'products' table exists with 'product_id' and 'category'.", "answer": "SELECT p.category, SUM(oi.quantity * oi.price) as total_revenue
FROM orders o
JOIN order_items oi ON o.order_id = oi.order_id
JOIN products p ON oi.product_id = p.product_id
WHERE o.order_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY p.category;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to identify customers who have placed more than 5 orders in the last year. Tables: 'customers' (customer_id, name), 'orders' (order_id, customer_id, order_date).", "answer": "SELECT c.customer_id, c.name
FROM customers c
JOIN orders o ON c.customer_id = o.customer_id
WHERE o.order_date >= DATE_SUB(CURDATE(), INTERVAL 1 YEAR)
GROUP BY c.customer_id, c.name
HAVING COUNT(o.order_id) > 5;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a SQL query to update the status of all orders to 'archived' if they were placed more than 2 years ago and have no associated items in the 'order_items' table. Tables: 'orders' (order_id, status, order_date), 'order_items' (order_id).", "answer": "UPDATE orders
SET status = 'archived'
WHERE order_date < DATE_SUB(CURDATE(), INTERVAL 2 YEAR)
AND order_id NOT IN (SELECT DISTINCT order_id FROM order_items);", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a JSON output of customer names and their total spending for the current month using a SQL query that returns JSON format. Tables: 'customers' (customer_id, name), 'orders' (order_id, customer_id, order_date, total_amount).", "answer": "SELECT JSON_OBJECT('customers', JSON_ARRAYAGG(JSON_OBJECT('name', c.name, 'total_spending', SUM(o.total_amount))))
FROM customers c
JOIN orders o ON c.customer_id = o.customer_id
WHERE o.order_date >= DATE_TRUNC('month', CURRENT_DATE)
GROUP BY c.customer_id, c.name;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to find the top 3 products by sales volume in each category. Tables: 'products' (product_id, name, category), 'order_items' (order_id, product_id, quantity).", "answer": "WITH RankedProducts AS (
  SELECT p.product_id, p.name, p.category, SUM(oi.quantity) as total_qty,
         RANK() OVER (PARTITION BY p.category ORDER BY SUM(oi.quantity) DESC) as rank
  FROM products p
  JOIN order_items oi ON p.product_id = oi.product_id
  GROUP BY p.product_id, p.name, p.category
)
SELECT product_id, name, category, total_qty
FROM RankedProducts
WHERE rank <= 3;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a SQL query to detect duplicate email addresses in the 'users' table and return the email and count of occurrences. Table: 'users' (user_id, email).", "answer": "SELECT email, COUNT(*) as occurrence_count
FROM users
GROUP BY email
HAVING COUNT(*) > 1;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL query to calculate the month-over-month growth rate of orders. Tables: 'orders' (order_id, order_date). Assume you need the count of orders per month.", "answer": "WITH MonthlyOrders AS (
  SELECT DATE_TRUNC('month', order_date) as month, COUNT(*) as order_count
  FROM orders
  GROUP BY DATE_TRUNC('month', order_date)
)
SELECT month, order_count,
       (order_count - LAG(order_count) OVER (ORDER BY month)) * 100.0 / LAG(order_count) OVER (ORDER BY month) as growth_rate
FROM MonthlyOrders;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to find customers who have never placed an order. Tables: 'customers' (customer_id, name), 'orders' (order_id, customer_id).", "answer": "SELECT customer_id, name
FROM customers
WHERE customer_id NOT IN (SELECT DISTINCT customer_id FROM orders);", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a SQL query to pivot order status counts into columns for each month. Tables: 'orders' (order_id, order_date, status). Statuses are 'completed', 'pending', 'cancelled'.", "answer": "SELECT DATE_TRUNC('month', order_date) as month,
       SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) as completed_count,
       SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) as pending_count,
       SUM(CASE WHEN status = 'cancelled' THEN 1 ELSE 0 END) as cancelled_count
FROM orders
GROUP BY DATE_TRUNC('month', order_date)
ORDER BY month;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL query to find the average order value for each customer, but only include customers with at least 2 orders. Tables: 'orders' (order_id, customer_id, total_amount).", "answer": "SELECT customer_id, AVG(total_amount) as avg_order_value
FROM orders
GROUP BY customer_id
HAVING COUNT(order_id) >= 2;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to find the total sales amount for each product category in the year 2023, ordered by total sales descending. Assume tables: products (id, category_id, name), categories (id, name), sales (id, product_id, amount, sale_date).", "answer": "SELECT c.name AS category_name, SUM(s.amount) AS total_sales
FROM sales s
JOIN products p ON s.product_id = p.id
JOIN categories c ON p.category_id = c.id
WHERE YEAR(s.sale_date) = 2023
GROUP BY c.name
ORDER BY total_sales DESC;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Generate a SQL query to identify customers who have made more than 5 purchases in the last 30 days. Tables: customers (id, name), orders (id, customer_id, order_date, status).", "answer": "SELECT c.name, COUNT(o.id) AS purchase_count
FROM customers c
JOIN orders o ON c.id = o.customer_id
WHERE o.order_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND o.status = 'completed'
GROUP BY c.name
HAVING purchase_count > 5;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Create a SQL query to retrieve the top 10 most expensive products from the 'Electronics' category. Tables: products (id, name, price, category_id), categories (id, name).", "answer": "SELECT p.name, p.price
FROM products p
JOIN categories c ON p.category_id = c.id
WHERE c.name = 'Electronics'
ORDER BY p.price DESC
LIMIT 10;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Write a SQL query to find the average order value per customer for orders placed in 2022. Tables: orders (id, customer_id, total_amount, order_date).", "answer": "SELECT customer_id, AVG(total_amount) AS avg_order_value
FROM orders
WHERE YEAR(order_date) = 2022
GROUP BY customer_id;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Generate a SQL query to list all employees who earn more than the average salary of their department. Tables: employees (id, name, salary, department_id), departments (id, name).", "answer": "SELECT e.name, e.salary, d.name AS department_name
FROM employees e
JOIN departments d ON e.department_id = d.id
WHERE e.salary > (
    SELECT AVG(salary)
    FROM employees e2
    WHERE e2.department_id = e.department_id
);", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Create a SQL query to find the second highest salary from the employees table. Tables: employees (id, name, salary).", "answer": "SELECT DISTINCT salary
FROM employees
ORDER BY salary DESC
LIMIT 1 OFFSET 1;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Write a SQL query to count the number of active users who logged in within the last 7 days. Tables: users (id, username, last_login), user_status (user_id, status).", "answer": "SELECT COUNT(u.id) AS active_user_count
FROM users u
JOIN user_status us ON u.id = us.user_id
WHERE us.status = 'active'
AND u.last_login >= DATE_SUB(CURDATE(), INTERVAL 7 DAY);", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Generate a SQL query to retrieve product names and their total inventory count, filtering for products with inventory less than 10. Tables: products (id, name), inventory (product_id, quantity).", "answer": "SELECT p.name, SUM(i.quantity) AS total_inventory
FROM products p
JOIN inventory i ON p.id = i.product_id
GROUP BY p.name
HAVING total_inventory < 10;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Create a SQL query to find customers who have never placed an order. Tables: customers (id, name), orders (id, customer_id).", "answer": "SELECT c.name
FROM customers c
LEFT JOIN orders o ON c.id = o.customer_id
WHERE o.id IS NULL;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Write a SQL query to calculate the monthly revenue for the year 2023. Tables: sales (id, amount, sale_date).", "answer": "SELECT DATE_FORMAT(sale_date, '%Y-%m') AS month, SUM(amount) AS monthly_revenue
FROM sales
WHERE YEAR(sale_date) = 2023
GROUP BY month
ORDER BY month;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Generate a SQL query to find the total revenue per customer for orders placed in 2023, sorted by revenue descending. The database has tables 'customers' (id, name) and 'orders' (id, customer_id, amount, order_date).", "answer": "SELECT c.name, SUM(o.amount) as total_revenue FROM customers c JOIN orders o ON c.id = o.customer_id WHERE YEAR(o.order_date) = 2023 GROUP BY c.id, c.name ORDER BY total_revenue DESC;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Write a SQL query to identify users who have not logged in for the past 90 days. Tables: 'users' (id, email, last_login).", "answer": "SELECT id, email FROM users WHERE last_login < DATE_SUB(CURDATE(), INTERVAL 90 DAY);", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Create a SQL query to calculate the average order value for each product category. Tables: 'products' (id, category_id, price), 'categories' (id, name), 'order_items' (product_id, quantity). Assume order_items has a unit_price field.", "answer": "SELECT cat.name, AVG(oi.unit_price * oi.quantity) as avg_order_value FROM categories cat JOIN products p ON cat.id = p.category_id JOIN order_items oi ON p.id = oi.product_id GROUP BY cat.id, cat.name;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Generate a SQL query to find the second highest salary from the 'employees' table (id, name, salary).", "answer": "SELECT MAX(salary) as second_highest_salary FROM employees WHERE salary < (SELECT MAX(salary) FROM employees);", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Write a SQL query to pivot the 'sales' table (year, region, amount) into columns for each region (North, South, East, West).", "answer": "SELECT year, SUM(CASE WHEN region = 'North' THEN amount ELSE 0 END) as North, SUM(CASE WHEN region = 'South' THEN amount ELSE 0 END) as South, SUM(CASE WHEN region = 'East' THEN amount ELSE 0 END) as East, SUM(CASE WHEN region = 'West' THEN amount ELSE 0 END) as West FROM sales GROUP BY year;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Create a SQL query to delete duplicate records from the 'contacts' table (id, email, phone), keeping only the record with the lowest id for each email.", "answer": "DELETE c1 FROM contacts c1 INNER JOIN contacts c2 WHERE c1.email = c2.email AND c1.id > c2.id;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Generate a SQL query to find customers who have ordered both 'Product A' and 'Product B'. Tables: 'customers' (id, name), 'orders' (id, customer_id, product_name).", "answer": "SELECT DISTINCT c.name FROM customers c JOIN orders o1 ON c.id = o1.customer_id JOIN orders o2 ON c.id = o2.customer_id WHERE o1.product_name = 'Product A' AND o2.product_name = 'Product B';", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Write a SQL query to calculate the running total of sales for each month. Tables: 'sales' (id, sale_date, amount).", "answer": "SELECT sale_date, amount, SUM(amount) OVER (ORDER BY sale_date) as running_total FROM sales;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Create a SQL query to find the top 3 products by sales volume in each category. Tables: 'products' (id, category_id, name), 'sales' (product_id, quantity).", "answer": "WITH RankedProducts AS (SELECT p.category_id, p.name, SUM(s.quantity) as total_qty, RANK() OVER (PARTITION BY p.category_id ORDER BY SUM(s.quantity) DESC) as rank FROM products p JOIN sales s ON p.id = s.product_id GROUP BY p.category_id, p.name) SELECT category_id, name, total_qty FROM RankedProducts WHERE rank <= 3;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Generate a SQL query to convert a JSON column 'metadata' in the 'products' table to extract the 'color' field.", "answer": "SELECT id, name, metadata->>'$.color' as color FROM products;", "subject": "SQL", "category": "SQL / JSON Generation"}
{"question": "Given a table 'users' with columns 'id', 'name', 'email', 'created_at', write a SQL query to find the top 5 users who registered in the last 30 days, ordered by registration date descending.", "answer": "SELECT id, name, email, created_at FROM users WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) ORDER BY created_at DESC LIMIT 5;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to calculate the total sales amount per product from an 'orders' table with columns 'order_id', 'product_id', 'quantity', 'price'.", "answer": "SELECT product_id, SUM(quantity * price) as total_sales FROM orders GROUP BY product_id;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a JSON object representing a user profile from a SQL query result. The table 'profiles' has 'user_id', 'username', 'bio'. Output format: {"user_id": int, "username": string, "bio": string}.", "answer": "SELECT JSON_OBJECT('user_id', user_id, 'username', username, 'bio', bio) as profile_json FROM profiles LIMIT 1;", "subject": "Database", "category": "JSON Generation"}
{"question": "Write a SQL query to find duplicate emails in a 'customers' table with columns 'id', 'email', 'name'.", "answer": "SELECT email, COUNT(*) as count FROM customers GROUP BY email HAVING COUNT(*) > 1;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a SQL query to pivot data from a 'sales' table (columns: year, month, revenue) into columns for each month (Jan, Feb, Mar) for the year 2023.", "answer": "SELECT year, SUM(CASE WHEN month = 'Jan' THEN revenue END) as Jan, SUM(CASE WHEN month = 'Feb' THEN revenue END) as Feb, SUM(CASE WHEN month = 'Mar' THEN revenue END) as Mar FROM sales WHERE year = 2023 GROUP BY year;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL query to insert a new record into 'inventory' (id, item_name, stock_count) with values 101, 'Widget', 50.", "answer": "INSERT INTO inventory (id, item_name, stock_count) VALUES (101, 'Widget', 50);", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to retrieve the second highest salary from an 'employees' table with columns 'id', 'name', 'salary'.", "answer": "SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a JSON array of all active users from a 'users' table (columns: id, name, status). Filter where status is 'active'.", "answer": "SELECT JSON_ARRAYAGG(JSON_OBJECT('id', id, 'name', name)) FROM users WHERE status = 'active';", "subject": "Database", "category": "JSON Generation"}
{"question": "Write a SQL query to delete all records from 'logs' table where the log_date is older than 1 year.", "answer": "DELETE FROM logs WHERE log_date < DATE_SUB(CURDATE(), INTERVAL 1 YEAR);", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL query to join 'orders' (order_id, user_id) and 'users' (user_id, name) to get order details with user names.", "answer": "SELECT o.order_id, u.name, o.order_id FROM orders o JOIN users u ON o.user_id = u.user_id;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL query to extract the top 5 customers by total order value from the 'orders' table, joining with the 'customers' table to get their names. The result should include customer name and total value, sorted descending.", "answer": "SELECT c.customer_name, SUM(o.order_value) AS total_value FROM customers c JOIN orders o ON c.customer_id = o.customer_id GROUP BY c.customer_name ORDER BY total_value DESC LIMIT 5;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to find all employees who have not been assigned to any project in the 'projects' table. Assume 'employee_projects' links employees to projects.", "answer": "SELECT e.employee_name FROM employees e LEFT JOIN employee_projects ep ON e.employee_id = ep.employee_id WHERE ep.project_id IS NULL;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a JSON object representing a user profile with fields: id (integer), name (string), and tags (array of strings). Use the values: id=101, name='Alice', tags=['admin', 'developer'].", "answer": "{"id": 101, "name": "Alice", "tags": ["admin", "developer"]}", "subject": "Data Formats", "category": "JSON Generation"}
{"question": "Generate a SQL query to pivot the 'sales' table, showing total sales per region for each year (2021, 2022). Columns should be region, sales_2021, sales_2022.", "answer": "SELECT region, SUM(CASE WHEN year = 2021 THEN amount ELSE 0 END) AS sales_2021, SUM(CASE WHEN year = 2022 THEN amount ELSE 0 END) AS sales_2022 FROM sales GROUP BY region;", "subject": "Database", "category": "SQL Generation"}
{"question": "Produce a JSON array of objects for a list of books. Each object must have 'title' (string) and 'price' (number). Include two books: 'The Great Gatsby' ($10.99) and '1984' ($8.50).", "answer": "[{"title": "The Great Gatsby", "price": 10.99}, {"title": "1984", "price": 8.50}]", "subject": "Data Formats", "category": "JSON Generation"}
{"question": "Write a SQL query to calculate the moving average of daily revenue over a 7-day window for the 'daily_revenue' table, ordered by date.", "answer": "SELECT date, revenue, AVG(revenue) OVER (ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d FROM daily_revenue;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL query to delete duplicate records from the 'contacts' table based on the 'email' column, keeping only the record with the highest 'id'.", "answer": "DELETE FROM contacts WHERE id NOT IN (SELECT MAX(id) FROM contacts GROUP BY email);", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a JSON schema definition for a 'product' object. It must have 'sku' (string, required), 'price' (number, required), and 'description' (string, optional).", "answer": "{"type": "object", "properties": {"sku": {"type": "string"}, "price": {"type": "number"}, "description": {"type": "string"}}, "required": ["sku", "price"]}", "subject": "Data Formats", "category": "JSON Generation"}
{"question": "Write a SQL query to find the second highest salary from the 'employees' table. Handle cases where there might not be a second highest salary.", "answer": "SELECT MAX(salary) FROM employees WHERE salary < (SELECT MAX(salary) FROM employees);", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a JSON object representing a configuration for a web server. Keys: 'port' (integer, default 8080), 'debug' (boolean, default false), 'log_level' (string, default 'info').", "answer": "{"port": 8080, "debug": false, "log_level": "info"}", "subject": "Data Formats", "category": "JSON Generation"}
{"question": "Generate a SQL query to find the total sales amount per product category for orders placed in the last 30 days. The output should include category_name and total_sales, sorted by total_sales descending.", "answer": "SELECT p.category_name, SUM(o.amount) AS total_sales
FROM orders o
JOIN products p ON o.product_id = p.id
WHERE o.order_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
GROUP BY p.category_name
ORDER BY total_sales DESC;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to identify users who have logged in on consecutive days for at least 3 days within the last month. Return user_id and the start date of the streak.", "answer": "WITH login_dates AS (
  SELECT DISTINCT user_id, DATE(login_time) as login_day
  FROM user_logs
  WHERE login_time >= DATE_SUB(CURDATE(), INTERVAL 1 MONTH)
),
ranked AS (
  SELECT user_id, login_day,
         DATE_SUB(login_day, INTERVAL ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_day) DAY) as grp
  FROM login_dates
),
streaks AS (
  SELECT user_id, grp, COUNT(*) as streak_length
  FROM ranked
  GROUP BY user_id, grp
  HAVING streak_length >= 3
)
SELECT user_id, MIN(login_day) as start_date
FROM ranked
WHERE (user_id, grp) IN (SELECT user_id, grp FROM streaks)
GROUP BY user_id, grp
ORDER BY start_date;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a JSON object representing a user profile with fields: id, name, email, and tags. The tags should be an array of strings extracted from a comma-separated string in the database column 'user_tags'.", "answer": "SELECT JSON_OBJECT(
  'id', id,
  'name', name,
  'email', email,
  'tags', JSON_ARRAYAGG(TRIM(tag))
) AS user_profile
FROM (
  SELECT id, name, email, SUBSTRING_INDEX(SUBSTRING_INDEX(user_tags, ',', numbers.n), ',', -1) AS tag
  FROM users
  JOIN (
    SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5
  ) numbers
  ON CHAR_LENGTH(user_tags) - CHAR_LENGTH(REPLACE(user_tags, ',', '')) >= numbers.n - 1
) AS tags
GROUP BY id, name, email;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to calculate the moving average of daily active users over a 7-day window for the past 3 months. Output date and moving_avg.", "answer": "SELECT date, AVG(dau) OVER (ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg
FROM (
  SELECT DATE(created_at) as date, COUNT(DISTINCT user_id) as dau
  FROM user_activity
  WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 3 MONTH)
  GROUP BY DATE(created_at)
) AS daily_counts
ORDER BY date;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL query to pivot sales data from rows to columns, showing monthly sales for each product. Columns should be Jan, Feb, Mar, etc., and rows should be product_id.", "answer": "SELECT product_id,
       SUM(CASE WHEN MONTH(sale_date) = 1 THEN amount ELSE 0 END) AS Jan,
       SUM(CASE WHEN MONTH(sale_date) = 2 THEN amount ELSE 0 END) AS Feb,
       SUM(CASE WHEN MONTH(sale_date) = 3 THEN amount ELSE 0 END) AS Mar,
       SUM(CASE WHEN MONTH(sale_date) = 4 THEN amount ELSE 0 END) AS Apr,
       SUM(CASE WHEN MONTH(sale_date) = 5 THEN amount ELSE 0 END) AS May,
       SUM(CASE WHEN MONTH(sale_date) = 6 THEN amount ELSE 0 END) AS Jun
FROM sales
WHERE YEAR(sale_date) = 2023
GROUP BY product_id;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to find the top 5 customers by total spending in each region. Include customer_name, region, and total_spent.", "answer": "WITH customer_spending AS (
  SELECT c.customer_name, c.region, SUM(o.amount) as total_spent
  FROM customers c
  JOIN orders o ON c.id = o.customer_id
  GROUP BY c.customer_name, c.region
),
ranked AS (
  SELECT customer_name, region, total_spent,
         ROW_NUMBER() OVER (PARTITION BY region ORDER BY total_spent DESC) as rn
