{"question": "Generate a SQL statement to create a view 'v_customer_summary' that outputs customer_id and a JSON object 'last_order' containing order_date and total_amount from the 'orders' table, limited to the most recent order per customer.", "answer": "CREATE VIEW v_customer_summary AS SELECT customer_id, JSON_BUILD_OBJECT('order_date', order_date, 'total_amount', total_amount) AS last_order FROM (SELECT customer_id, order_date, total_amount, ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY order_date DESC) as rn FROM orders) t WHERE rn = 1;", "subject": "Database", "category": "SQL Generation"}
