JOIN departments d ON e.department_id = d.id
GROUP BY d.name
ORDER BY avg_salary DESC
LIMIT 1;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate an SQL query to find the total sales per product category for orders placed in 2023, sorted by total sales descending. Tables: orders (order_id, customer_id, order_date), order_items (order_id, product_id, quantity, price), products (product_id, category_id), categories (category_id, category_name).", "answer": "SELECT c.category_name, SUM(oi.quantity * oi.price) AS total_sales
FROM orders o
JOIN order_items oi ON o.order_id = oi.order_id
JOIN products p ON oi.product_id = p.product_id
JOIN categories c ON p.category_id = c.category_id
WHERE YEAR(o.order_date) = 2023
GROUP BY c.category_name
ORDER BY total_sales DESC;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to identify customers who have placed more than 5 orders in the last 6 months. Tables: customers (customer_id, name), orders (order_id, customer_id, order_date).", "answer": "SELECT c.customer_id, c.name, COUNT(o.order_id) AS order_count
