{"question": "Write a SQL query to pivot the 'inventory' table (columns: warehouse, item, quantity) into a format where warehouses are columns and items are rows.", "answer": "SELECT item, SUM(CASE WHEN warehouse = 'A' THEN quantity ELSE 0 END) as warehouse_a, SUM(CASE WHEN warehouse = 'B' THEN quantity ELSE 0 END) as warehouse_b FROM inventory GROUP BY item;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a SQL query to return a JSON object for each order containing the order_id and a nested object 'customer' with name and email from 'orders' and 'customers' tables.", "answer": "SELECT o.id, JSON_OBJECT('name', c.name, 'email', c.email) as customer FROM orders o JOIN customers c ON o.customer_id = c.id;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to identify users who have not logged in for more than 30 days, assuming 'last_login' is a timestamp column in 'users'.", "answer": "SELECT id, name FROM users WHERE last_login < NOW() - INTERVAL 30 DAY;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to extract the JSON 'metadata' field from a column named 'payload' in the 'logs' table, filtering for records where the 'status' is 'error'.", "answer": "SELECT JSON_EXTRACT(payload, '$.metadata') AS metadata FROM logs WHERE status = 'error';", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL statement to convert a JSON array stored in the 'tags' column into separate rows for each item in the 'products' table.", "answer": "SELECT id, JSON_UNQUOTE(JSON_EXTRACT(tags, CONCAT('$[', n.n, ']'))) AS tag FROM products, (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4) n WHERE JSON_LENGTH(tags) > n.n;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a SQL query that returns the 'user_id' and the value of the 'role' key from the 'permissions' JSON column, but only if the role is 'admin'.", "answer": "SELECT user_id, permissions->'$.role' AS role FROM users WHERE permissions->'$.role' = 'admin';", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to generate a JSON object containing 'id', 'name', and 'email' from the 'customers' table, formatted as a single JSON string per row.", "answer": "SELECT JSON_OBJECT('id', id, 'name', name, 'email', email) AS customer_json FROM customers;", "subject": "Database", "category": "SQL Generation"}
{"question": "Construct a SQL query to find all records in the 'events' table where the 'data' JSON column contains a key 'type' with value 'click'.", "answer": "SELECT * FROM events WHERE JSON_EXTRACT(data, '$.type') = 'click';", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL statement to update the 'score' field inside the 'stats' JSON column to 100 for the user with id 5 in the 'profiles' table.", "answer": "UPDATE profiles SET stats = JSON_SET(stats, '$.score', 100) WHERE id = 5;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to extract the 'timestamp' from the 'event_log' JSON column in the 'audit' table and format it as a standard datetime string.", "answer": "SELECT STR_TO_DATE(JSON_EXTRACT(event_log, '$.timestamp'), '%Y-%m-%dT%H:%i:%s') AS formatted_time FROM audit;", "subject": "Database", "category": "SQL Generation"}
{"question": "Create a SQL query to return the 'id' and the count of items in the 'cart_items' JSON array column for orders with a total greater than 50.", "answer": "SELECT id, JSON_LENGTH(cart_items) AS item_count FROM orders WHERE total > 50;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL statement to merge two JSON columns 'config_a' and 'config_b' into a new column 'merged_config' in the 'settings' table, with 'config_a' taking precedence.", "answer": "UPDATE settings SET merged_config = JSON_MERGE_PRESERVE(config_a, config_b);", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to select records from 'inventory' where the 'details' JSON column does NOT contain the key 'discontinued'.", "answer": "SELECT * FROM inventory WHERE JSON_CONTAINS_PATH(details, 'one', '$.discontinued') = 0;", "subject": "Database", "category": "SQL Generation"}
{"question": "Generate a SQL query to find the total revenue per customer for orders placed in 2023. The database has tables 'customers' (id, name) and 'orders' (id, customer_id, amount, order_date).", "answer": "SELECT c.name, SUM(o.amount) as total_revenue FROM customers c JOIN orders o ON c.id = o.customer_id WHERE YEAR(o.order_date) = 2023 GROUP BY c.id, c.name;", "subject": "Database", "category": "SQL Generation"}
{"question": "Write a SQL query to identify duplicate email addresses in the 'users' table (id, email, created_at). Return the email and the count of occurrences.", "answer": "SELECT email, COUNT(*) as count FROM users GROUP BY email HAVING COUNT(*) > 1;", "subject": "Database", "category": "SQL Generation"}
